# hypothesis: PEP 695 infers covariance for a Box[T] that only exposes T and invariance for Store[T] that also accepts T, so Box[bool] is accepted as Box[int] while Store[bool] is rejected as Store[int].
from dataclasses import dataclass
from typing import reveal_type


@dataclass(frozen=True)
class Box[T]:
    item: T

    def get(self) -> T:
        return self.item


class Store[T]:
    def __init__(self, item: T) -> None:
        self.item = item

    def get(self) -> T:
        return self.item

    def put(self, item: T) -> None:
        self.item = item


def read_int(box: Box[int]) -> int:
    return box.get()


def write_int(store: Store[int], value: int) -> None:
    store.put(value)


flag = Box(True)
reveal_type(flag)
print(read_int(flag))

store_bool = Store(False)
reveal_type(store_bool)
write_int(store_bool, 3)  # expect-error: Store is invariant in T
print(store_bool.get())
